<?php
session_start();
require_once __DIR__ . '/game_mode_access.php';
requireGameModeAccess('masked_impostor');

$questions = $_SESSION['quiz_data']['questions'] ?? [];
if (empty($questions)) { header("Location: quizzes.php?error=no_questions_found"); exit(); }
$mcq = [];
foreach ($questions as $q) {
    if (!empty($q['options']) && count($q['options']) >= 4 && (isset($q['answer_index']) || !empty($q['answer']))) {
        $mcq[] = $q;
    }
}
if (count($mcq) < 3) { header("Location: quizzes.php?error=not_enough_mcq_questions"); exit(); }
$title   = $_SESSION['quiz_data']['title'] ?? 'Case File';
$total_q = count($mcq);
?>
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0,maximum-scale=1.0">
<title>Detective Agency | PinnaQuest</title>
<link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&family=Fredoka+One&family=Special+Elite&display=swap" rel="stylesheet">
<style>
:root {
    --amber:#f59e0b; --amber-d:#b45309; --amber-dd:#78350f;
    --neon-red:#ff4444; --neon-blue:#3b9eff;
    --manila:#f0e6cc; --manila-d:#d4c49a;
    --ink:#1a1206; --ink-mid:#4a3920; --ink-dim:#8a7040;
    --green:#10b981; --green-d:#065f46;
    --red:#ef4444;   --red-d:#991b1b;
    --blue:#3b82f6;  --blue-d:#1d4ed8;
    --purple:#7c3aed;--purple-d:#5b21b6;
    --orange:#f97316;--orange-d:#c2410c;
    --font-head:'Fredoka One','Nunito',sans-serif;
    --font-body:'Nunito',sans-serif;
    --font-type:'Special Elite',serif;
}
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
html,body{width:100%;min-height:100vh;font-family:var(--font-body);background:#04060f;color:#e2e8f0;overflow-x:hidden;}

/* ── BACKGROUND ── */
#bg{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden;}
#bg-img{position:absolute;inset:0;background-size:cover;background-position:center;background-repeat:no-repeat;}
#bg-dim{position:absolute;inset:0;background:linear-gradient(180deg,rgba(4,6,15,.5) 0%,rgba(4,6,15,.35) 40%,rgba(4,6,15,.58) 75%,rgba(4,6,15,.82) 100%);}
#bg-glow{position:absolute;inset:0;background:radial-gradient(ellipse 300px 350px at 37% 68%,rgba(245,158,11,.28) 0%,transparent 70%),radial-gradient(ellipse 180px 200px at 72% 72%,rgba(245,130,20,.18) 0%,transparent 60%),radial-gradient(ellipse 120px 140px at 13% 60%,rgba(245,158,11,.12) 0%,transparent 60%);animation:glowPulse 4s ease-in-out infinite alternate;}
@keyframes glowPulse{0%{opacity:.85;}40%{opacity:1;}75%{opacity:.9;}100%{opacity:.95;}}
#bg-rain{position:absolute;inset:0;background-image:repeating-linear-gradient(102deg,transparent 0px,transparent 2px,rgba(180,210,255,.08) 2px,rgba(180,210,255,.08) 3px,transparent 3px,transparent 55px);background-size:55px 110px;animation:rainSlide .62s linear infinite;}
@keyframes rainSlide{from{background-position:0 -110px;}to{background-position:0 0;}}
#bg-fog{position:absolute;bottom:0;left:0;right:0;height:22%;background:linear-gradient(180deg,transparent,rgba(13,20,36,.5));filter:blur(22px);animation:fogDrift 14s ease-in-out infinite alternate;}
@keyframes fogDrift{from{transform:translateX(-5%);}to{transform:translateX(5%);}}
.neon-sign{position:absolute;font-family:var(--font-head);font-size:10px;letter-spacing:2px;text-transform:uppercase;font-weight:700;animation:signFlicker 3.5s ease-in-out infinite alternate;pointer-events:none;}
#ns1{top:18%;left:3%;color:#ff6060;text-shadow:0 0 8px #ff4444,0 0 22px #ff2222;}
#ns2{top:14%;right:4%;color:#60d0ff;text-shadow:0 0 8px #3b9eff,0 0 22px #1177ff;}
@keyframes signFlicker{0%,88%,100%{opacity:.75;}90%{opacity:.1;}94%{opacity:.75;}96%{opacity:.2;}}
#rain-layer{position:fixed;inset:0;z-index:1;pointer-events:none;overflow:hidden;}
.rain-drop{position:absolute;width:1.5px;pointer-events:none;background:linear-gradient(180deg,transparent,rgba(160,200,255,.35));border-radius:0 0 2px 2px;animation:rainFall var(--rd,.75s) linear var(--rl,0s) infinite;transform:rotate(8deg);transform-origin:top;}
@keyframes rainFall{0%{top:-30px;}100%{top:110vh;}}

/* ── HUD ── */
#hud{position:fixed;top:0;left:0;right:0;z-index:90;background:rgba(4,6,15,.97);border-bottom:2px solid rgba(245,158,11,.4);padding:7px 18px;display:flex;align-items:center;gap:12px;backdrop-filter:blur(10px);box-shadow:0 4px 24px rgba(0,0,0,.7);}
.hud-badge{width:34px;height:34px;flex-shrink:0;background:var(--amber);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;box-shadow:0 0 18px rgba(245,158,11,.55);border:2px solid var(--amber-d);}
.hud-title{font-family:var(--font-head);font-size:14px;line-height:1.15;color:var(--amber);text-shadow:0 0 16px rgba(245,158,11,.65);}
.hud-title span{display:block;font-family:var(--font-body);font-size:9px;font-weight:800;color:rgba(245,158,11,.35);letter-spacing:1.5px;text-transform:uppercase;}
.hud-spacer{flex:1;}
.hud-lives{display:flex;gap:5px;align-items:center;background:rgba(0,0,0,.45);border-radius:50px;padding:4px 12px;border:1px solid rgba(245,158,11,.25);}
.life-badge{font-size:16px;transition:.25s;filter:drop-shadow(0 0 4px rgba(245,158,11,.7));}
.life-badge.lost{filter:grayscale(1) opacity(.18);transform:scale(.6) rotate(-15deg);}
.hud-chip{background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.25);border-radius:10px;padding:4px 12px;text-align:center;min-width:56px;}
.hud-chip .v{font-family:var(--font-head);font-size:15px;color:var(--amber);display:block;}
.hud-chip .l{font-size:8px;color:rgba(245,158,11,.35);text-transform:uppercase;letter-spacing:.5px;font-weight:800;}
#invest-track{position:fixed;top:50px;left:0;right:0;height:4px;background:rgba(255,255,255,.05);z-index:89;}
#invest-fill{height:100%;background:linear-gradient(90deg,var(--amber),#fde68a);width:0%;transition:width .8s cubic-bezier(.34,1.56,.64,1);box-shadow:0 0 10px var(--amber);border-radius:0 4px 4px 0;}

/* ── SUSPECT BAR ── */
#suspect-bar{position:relative;z-index:5;max-width:1280px;margin:0 auto;padding:58px 14px 0;}
#suspect-bar-inner{background:rgba(4,6,15,.88);border:2px solid rgba(245,158,11,.35);border-radius:16px;padding:18px 18px 24px;box-shadow:0 0 50px rgba(0,0,0,.7),inset 0 0 30px rgba(245,158,11,.04),0 0 0 1px rgba(245,158,11,.1);backdrop-filter:blur(8px);}
.bar-eyebrow{font-family:var(--font-type);font-size:14px;color:rgba(245,158,11,.8);margin-bottom:14px;display:flex;align-items:center;gap:8px;letter-spacing:.5px;font-weight:700;}
#suspect-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:10px;}
@media(max-width:820px){#suspect-grid{grid-template-columns:repeat(3,1fr);}}
@media(max-width:440px){#suspect-grid{grid-template-columns:repeat(2,1fr);}}

/* ── CHARACTER CARDS ── */
.char-figure{display:flex;flex-direction:column;align-items:center;position:relative;padding:8px 6px 10px;background:rgba(0,0,0,.35);border:2px solid rgba(245,158,11,.18);border-radius:12px;transition:transform .25s cubic-bezier(.34,1.56,.64,1),border-color .3s,box-shadow .3s;cursor:default;overflow:hidden;}
.char-figure:hover{transform:translateY(-6px) scale(1.04);}
.lineup-num{position:absolute;top:8px;left:8px;z-index:10;background:var(--amber);color:var(--ink);font-family:var(--font-head);font-size:13px;width:30px;height:30px;border-radius:50%;display:flex;align-items:center;justify-content:center;border:2px solid var(--amber-d);box-shadow:0 2px 8px rgba(0,0,0,.6);}

/* Image wrapper — tall so full figure is visible */
.char-img-wrap{width:100%;height:280px;display:flex;align-items:center;justify-content:center;overflow:hidden;position:relative;}
.char-img{width:100%;height:100%;object-fit:contain;object-position:center center;mix-blend-mode:screen;filter:brightness(1.1) contrast(1.06);transition:transform .25s,filter .25s;display:block;transform:scale(2.40) translateY(5%);}
.char-figure:hover .char-img{transform:scale(2.90) translateY(5%);filter:brightness(1.18) contrast(1.1);}

/* Shadow-type characters: extra blue glow */
.type-shadow .char-img{filter:brightness(1.14) contrast(1.1) drop-shadow(0 0 16px rgba(59,158,255,.75));transform:scale(2.40) translateY(5%);}
.type-shadow:hover .char-img{filter:brightness(1.22) contrast(1.15) drop-shadow(0 0 28px rgba(59,158,255,1));transform:scale(2.90) translateY(5%);}

/* Spotlight cone for possible suspects */
.char-figure.possible::before{content:'';position:absolute;top:0;left:50%;transform:translateX(-50%);width:0;height:0;border-left:50px solid transparent;border-right:50px solid transparent;border-top:190px solid rgba(245,158,11,.07);pointer-events:none;z-index:0;}

/* Possible: pulsing amber border */
.char-figure.possible{border-color:var(--amber);box-shadow:0 0 0 2px var(--amber),0 0 24px rgba(245,158,11,.55),0 0 55px rgba(245,158,11,.18);animation:possiblePulse 2.2s ease-in-out infinite alternate;}
@keyframes possiblePulse{from{box-shadow:0 0 0 2px var(--amber),0 0 14px rgba(245,158,11,.45);}to{box-shadow:0 0 0 3px var(--amber),0 0 36px rgba(245,158,11,.8),0 0 70px rgba(245,158,11,.2);}}

/* Eliminated: grayscale + red X */
.char-figure.eliminated{opacity:.22;filter:grayscale(1) blur(.7px);}
.char-figure.eliminated::after{content:'✕';position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);font-size:56px;font-family:var(--font-head);color:var(--neon-red);text-shadow:0 0 28px rgba(255,0,0,.9);z-index:20;}

.char-nameplate{font-family:var(--font-type);font-size:13px;color:rgba(245,230,190,1);text-align:center;line-height:1.35;margin-top:10px;text-shadow:0 1px 8px rgba(0,0,0,.9);min-height:32px;max-width:100%;font-weight:700;}
.char-traits{display:flex;gap:3px;flex-wrap:wrap;justify-content:center;margin-top:3px;}
.char-traits span{font-size:12px;background:rgba(4,6,15,.8);border:1px solid rgba(245,158,11,.4);border-radius:20px;padding:3px 8px;color:rgba(245,230,190,.9);font-weight:700;}

/* ── GAME LAYOUT ── */
#game-wrap{position:relative;z-index:5;max-width:1280px;margin:0 auto;padding:14px 14px 60px;display:grid;grid-template-columns:1.55fr 1fr;gap:18px;align-items:start;}
@media(max-width:820px){#game-wrap{grid-template-columns:1fr;}}
#timer-track{width:100%;height:9px;background:rgba(255,255,255,.05);border-radius:50px;overflow:hidden;margin-bottom:14px;border:1px solid rgba(245,158,11,.15);}
#timer-fill{height:100%;border-radius:50px;background:linear-gradient(90deg,var(--green),#6ee7b7);transition:width 1s linear;box-shadow:0 0 10px rgba(16,185,129,.5);}
#timer-fill.danger{background:linear-gradient(90deg,var(--red),#fca5a5);box-shadow:0 0 10px rgba(239,68,68,.6);animation:timerPulse .6s ease infinite alternate;}
@keyframes timerPulse{from{opacity:1;}to{opacity:.55;}}
.q-eyebrow{font-family:var(--font-type);font-size:11px;color:rgba(245,158,11,.45);margin-bottom:10px;display:flex;align-items:center;gap:7px;letter-spacing:.5px;}

/* Case file card */
.q-card{background:var(--manila);border:3px solid #c4a870;border-radius:4px 4px 4px 18px;padding:22px 22px 18px;margin-bottom:14px;box-shadow:5px 5px 0 rgba(139,100,35,.55),0 14px 32px rgba(0,0,0,.65);position:relative;}
.q-card::before{content:'';position:absolute;top:0;right:0;width:0;height:0;border-style:solid;border-width:0 28px 28px 0;border-color:transparent #8b6423 transparent transparent;}
.q-card::after{content:'';position:absolute;top:0;right:0;width:26px;height:26px;background:#d4c49a;clip-path:polygon(100% 0,100% 100%,0 100%);}
.q-card-label{font-family:var(--font-type);font-size:9px;letter-spacing:2px;color:var(--ink-dim);text-transform:uppercase;margin-bottom:12px;padding-bottom:8px;border-bottom:1px dashed var(--manila-d);display:flex;align-items:center;gap:8px;}
.q-card-label::before{content:'📋';font-size:12px;}
.q-text{font-family:var(--font-body);font-weight:700;font-size:1.15rem;line-height:1.55;color:var(--ink);}

/* Answer buttons */
.answers-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;}
.ans-btn{position:relative;display:flex;align-items:stretch;border-radius:6px;border:3px solid;background:var(--manila);cursor:pointer;overflow:hidden;min-height:62px;text-align:left;padding:0;transition:transform .12s cubic-bezier(.34,1.56,.64,1),box-shadow .12s;box-shadow:0 5px 0 var(--btn-shadow,#555);}
.ans-btn.opt-0{border-color:var(--orange);--btn-shadow:var(--orange-d);}
.ans-btn.opt-1{border-color:var(--blue);--btn-shadow:var(--blue-d);}
.ans-btn.opt-2{border-color:var(--green);--btn-shadow:var(--green-d);}
.ans-btn.opt-3{border-color:var(--purple);--btn-shadow:var(--purple-d);}
.ans-btn:hover:not(:disabled){transform:translateY(-3px);box-shadow:0 8px 0 var(--btn-shadow,#555);}
.ans-btn:active:not(:disabled){transform:translateY(3px);box-shadow:0 2px 0 var(--btn-shadow,#555);}
.ans-btn:disabled{cursor:default;}
.ans-badge-wrap{width:50px;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.04);border-right:3px solid;border-color:inherit;}
.ans-btn.opt-0 .ans-badge{background:var(--orange);}
.ans-btn.opt-1 .ans-badge{background:var(--blue);}
.ans-btn.opt-2 .ans-badge{background:var(--green);}
.ans-btn.opt-3 .ans-badge{background:var(--purple);}
.ans-badge{width:30px;height:30px;border-radius:8px;color:#fff;font-family:var(--font-head);font-size:.95rem;display:flex;align-items:center;justify-content:center;box-shadow:0 3px 7px rgba(0,0,0,.35);}
.ans-text{flex:1;padding:10px 12px;display:flex;align-items:center;font-size:.93rem;font-weight:700;color:var(--ink);line-height:1.35;}
.ans-btn.correct-flash{border-color:var(--green)!important;background:#d1fae5!important;box-shadow:0 5px 0 var(--green-d),0 0 0 4px rgba(16,185,129,.3)!important;animation:correctBounce .45s cubic-bezier(.34,1.56,.64,1);}
.ans-btn.wrong-fade{opacity:.25;filter:grayscale(.7);transform:none!important;box-shadow:none!important;}
@keyframes correctBounce{0%{transform:scale(1)}40%{transform:scale(1.05) translateY(-3px)}100%{transform:scale(1)}}
#score-footer{margin-top:12px;display:flex;justify-content:space-between;align-items:center;font-family:var(--font-type);font-size:11px;color:rgba(245,158,11,.3);border-top:1px dashed rgba(245,158,11,.15);padding-top:10px;}
#score-val{color:var(--amber);font-size:17px;}

/* Evidence panel */
.panel{background:rgba(4,6,15,.88);border:2px solid rgba(245,158,11,.22);border-radius:12px;padding:16px;box-shadow:0 8px 28px rgba(0,0,0,.65),inset 0 0 20px rgba(245,158,11,.02);backdrop-filter:blur(8px);}
.panel-title{font-family:var(--font-type);font-size:13px;color:rgba(245,158,11,.8);margin-bottom:12px;display:flex;align-items:center;gap:8px;text-shadow:0 0 10px rgba(245,158,11,.4);border-bottom:1px dashed rgba(245,158,11,.15);padding-bottom:10px;}
.clue-list{display:flex;flex-direction:column;gap:9px;max-height:310px;overflow-y:auto;padding-right:4px;}
.clue-list::-webkit-scrollbar{width:4px;}
.clue-list::-webkit-scrollbar-thumb{background:rgba(245,158,11,.3);border-radius:10px;}
.clue-item{background:var(--manila);border:2px solid #c4a870;border-radius:6px;padding:8px 28px 8px 10px;color:var(--ink);font-family:var(--font-type);font-size:11.5px;line-height:1.5;box-shadow:2px 2px 0 rgba(139,100,35,.4);animation:clueSlide .4s cubic-bezier(.34,1.56,.64,1);position:relative;}
.clue-item::after{content:'🔎';position:absolute;top:5px;right:6px;font-size:12px;}
.clue-num{display:inline-block;background:var(--amber);color:var(--ink);border-radius:4px;font-size:9px;font-weight:800;padding:1px 5px;margin-right:6px;}
@keyframes clueSlide{from{opacity:0;transform:translateX(16px) scale(.95);}to{opacity:1;transform:translateX(0) scale(1);}}
.clue-empty{font-family:var(--font-type);font-size:11px;color:rgba(245,158,11,.22);text-align:center;padding:20px 8px;line-height:1.6;}

/* Feedback */
#feedback-banner{position:fixed;top:64px;left:50%;transform:translateX(-50%) translateY(-24px);z-index:150;padding:10px 24px;border-radius:6px;border:3px solid transparent;font-family:var(--font-type);font-size:13px;opacity:0;pointer-events:none;transition:.25s;box-shadow:0 6px 0 rgba(0,0,0,.4),0 12px 28px rgba(0,0,0,.5);white-space:nowrap;}
#feedback-banner.show{opacity:1;transform:translateX(-50%) translateY(0);}
#feedback-banner.ok{background:linear-gradient(135deg,var(--green),#6ee7b7);border-color:var(--green-d);color:#fff;}
#feedback-banner.bad{background:linear-gradient(135deg,var(--red),#fca5a5);border-color:var(--red-d);color:#fff;}

/* Overlays */
.overlay{position:fixed;inset:0;z-index:300;background:rgba(2,3,8,.93);backdrop-filter:blur(14px);display:none;align-items:center;justify-content:center;padding:20px;}
.overlay.show{display:flex;}
.overlay-card{background:linear-gradient(160deg,#f5ecd4,#ece0c0);border:4px solid #c4a870;border-radius:4px 4px 4px 20px;padding:30px 26px;max-width:560px;width:100%;box-shadow:6px 6px 0 rgba(139,100,35,.5),0 30px 60px rgba(0,0,0,.85);text-align:center;animation:cardBounce .4s cubic-bezier(.34,1.56,.64,1);max-height:90vh;overflow-y:auto;position:relative;}
.overlay-card::before{content:'CLASSIFIED — PINNAQUEST PD';position:absolute;top:0;left:0;right:0;background:#1a1d2e;color:var(--amber);font-family:var(--font-type);font-size:9px;letter-spacing:3px;padding:5px;text-align:center;}
@keyframes cardBounce{from{transform:scale(.8) translateY(20px);opacity:0;}to{transform:scale(1) translateY(0);opacity:1;}}
.overlay-title{font-family:var(--font-head);font-size:1.9rem;color:#1a1206;margin-top:12px;margin-bottom:5px;}
.overlay-sub{font-family:var(--font-type);font-size:.95rem;color:var(--ink-mid);margin-bottom:20px;line-height:1.6;}
.rules-list{text-align:left;display:flex;flex-direction:column;gap:11px;margin-bottom:22px;}
.rule-row{display:flex;gap:10px;align-items:flex-start;}
.rule-icon{font-size:20px;flex-shrink:0;width:28px;text-align:center;}
.rule-text{font-family:var(--font-type);font-size:.88rem;line-height:1.6;color:var(--ink-mid);}
.rule-text b{color:#7a3a10;}
.btn-case{background:linear-gradient(145deg,#1a1d2e,#0d1117);color:var(--amber);border:3px solid rgba(245,158,11,.4);padding:13px 34px;border-radius:6px;font-family:var(--font-head);font-size:.95rem;cursor:pointer;box-shadow:0 6px 0 #000,0 10px 22px rgba(0,0,0,.5);transition:transform .1s,box-shadow .1s;text-shadow:0 0 12px rgba(245,158,11,.6);}
.btn-case:hover{transform:translateY(-3px);box-shadow:0 9px 0 #000;}
.btn-case:active{transform:translateY(4px);box-shadow:0 2px 0 #000;}
.scene-emoji{font-size:52px;margin-bottom:12px;display:block;animation:sceneFloat 2.4s ease-in-out infinite;}
@keyframes sceneFloat{0%,100%{transform:translateY(0);}50%{transform:translateY(-10px);}}
.scene-line{font-family:var(--font-type);font-size:.98rem;color:var(--ink-mid);line-height:1.75;margin-bottom:4px;}
.scene-line.highlight{color:#7a3a10;font-size:1.05rem;}
/* Accusation — dark background so mix-blend-mode:screen works */
.accuse-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:20px 0 10px;}
.accuse-card{background:#0a0d18;border:3px solid rgba(245,158,11,.35);border-radius:10px;padding:12px 8px 10px;cursor:pointer;transition:transform .2s cubic-bezier(.34,1.56,.64,1),box-shadow .2s,border-color .2s;box-shadow:0 4px 0 rgba(0,0,0,.6);display:flex;flex-direction:column;align-items:center;overflow:hidden;}
.accuse-card:hover{border-color:var(--neon-red);box-shadow:0 7px 0 var(--red-d),0 0 30px rgba(255,68,68,.3);transform:translateY(-5px) scale(1.04);}
.accuse-card .char-img-wrap{height:210px;width:100%;}
.accuse-card .char-nameplate{color:rgba(245,230,190,.85);text-shadow:0 1px 5px rgba(0,0,0,.9);}
/* Result */
.result-emoji{font-size:62px;margin-bottom:10px;display:block;animation:cardBounce .5s cubic-bezier(.34,1.56,.64,1);}
.result-stats{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;margin:16px 0;}
.rstat{background:#f5ecd4;border:2px solid #c4a870;border-radius:8px;padding:10px 16px;min-width:85px;box-shadow:2px 2px 0 rgba(139,100,35,.35);}
.rstat .rv{font-family:var(--font-head);font-size:1.5rem;color:#7a3a10;display:block;}
.rstat .rl{font-family:var(--font-type);font-size:9px;color:var(--ink-dim);text-transform:uppercase;letter-spacing:.5px;margin-top:3px;display:block;}
.xp-badge{display:inline-block;background:linear-gradient(135deg,var(--amber),var(--amber-d));border:3px solid var(--amber-dd);color:var(--ink);font-family:var(--font-head);font-size:.9rem;padding:8px 20px;border-radius:6px;margin:6px 0 18px;box-shadow:0 4px 0 var(--amber-dd);animation:cardBounce .4s .3s cubic-bezier(.34,1.56,.64,1) both;}
.result-btns{display:flex;gap:10px;justify-content:center;flex-wrap:wrap;}
.btn-ghost{background:#f5ecd4;border:3px solid #c4a870;color:#7a3a10;padding:11px 22px;border-radius:6px;font-family:var(--font-head);font-size:.88rem;cursor:pointer;box-shadow:0 4px 0 rgba(139,100,35,.4);transition:transform .1s,box-shadow .1s;}
.btn-ghost:hover{transform:translateY(-2px);box-shadow:0 6px 0 rgba(139,100,35,.4);}
.score-pop-fx{position:fixed;pointer-events:none;z-index:400;font-family:var(--font-head);font-size:22px;color:var(--amber);text-shadow:2px 2px 0 var(--amber-d),0 0 14px rgba(245,158,11,.8);animation:scoreFly 1.1s ease-out forwards;}
@keyframes scoreFly{0%{transform:translateY(0) scale(.8);opacity:1;}60%{transform:translateY(-60px) scale(1.15);opacity:1;}100%{transform:translateY(-105px) scale(.9);opacity:0;}}
.conf-bit{position:fixed;pointer-events:none;z-index:999;border-radius:2px;animation:confDrop var(--cd,2s) var(--cl,0s) ease-in forwards;}
@keyframes confDrop{0%{transform:translateY(-10px) rotate(0deg);opacity:1;}100%{transform:translateY(110vh) rotate(720deg);opacity:0;}}
@media(max-width:480px){.answers-grid{grid-template-columns:1fr;}.q-text{font-size:1.05rem;}.accuse-grid{grid-template-columns:repeat(2,1fr);}.char-img-wrap{height:190px;}}
</style>
</head>
<body>

<audio id="bg-music" loop preload="auto" style="display:none;">
  <source src="bgsounddetective.mp3" type="audio/mpeg">
</audio>

<div id="bg">
  <div id="bg-img"></div>
  <div id="bg-dim"></div>
  <div id="bg-glow"></div>
  <div id="bg-rain"></div>
  <div id="bg-fog"></div>
  <div class="neon-sign" id="ns1">SUSPECT</div>
  <div class="neon-sign" id="ns2">EVIDENCE</div>
</div>
<div id="rain-layer"></div>

<div id="hud">
  <div class="hud-badge">🔍</div>
  <div class="hud-title">DETECTIVE AGENCY<span><?php echo htmlspecialchars($title); ?></span></div>
  <div class="hud-spacer"></div>
  <div class="hud-lives" id="hud-lives">
    <span class="life-badge">🔑</span><span class="life-badge">🔑</span><span class="life-badge">🔑</span>
  </div>
  <div class="hud-chip"><span class="v" id="hud-q">1/<?php echo $total_q; ?></span><span class="l">Question</span></div>
  <div class="hud-chip"><span class="v" id="hud-score">0</span><span class="l">Score</span></div>
</div>
<div id="invest-track"><div id="invest-fill"></div></div>
<div id="feedback-banner"></div>

<div id="suspect-bar">
  <div id="suspect-bar-inner">
    <div class="bar-eyebrow">🚔 SUSPECT LINEUP — Rain hammers the precinct. Six faces, each hiding something...</div>
    <div id="suspect-grid"></div>
  </div>
</div>

<div id="game-wrap">
  <div>
    <div id="timer-track"><div id="timer-fill" style="width:100%"></div></div>
    <div class="q-eyebrow">🔦 Interrogation Room — Question in progress</div>
    <div class="q-card">
      <div class="q-card-label">Case File — Questioning Suspect</div>
      <div class="q-text" id="q-text">Loading...</div>
    </div>
    <div class="answers-grid" id="answers-grid">
      <button class="ans-btn opt-0" id="ans-0" onclick="answerQuestion(0)"><div class="ans-badge-wrap"><div class="ans-badge">A</div></div><span class="ans-text" id="ans-text-0"></span></button>
      <button class="ans-btn opt-1" id="ans-1" onclick="answerQuestion(1)"><div class="ans-badge-wrap"><div class="ans-badge">B</div></div><span class="ans-text" id="ans-text-1"></span></button>
      <button class="ans-btn opt-2" id="ans-2" onclick="answerQuestion(2)"><div class="ans-badge-wrap"><div class="ans-badge">C</div></div><span class="ans-text" id="ans-text-2"></span></button>
      <button class="ans-btn opt-3" id="ans-3" onclick="answerQuestion(3)"><div class="ans-badge-wrap"><div class="ans-badge">D</div></div><span class="ans-text" id="ans-text-3"></span></button>
    </div>
    <div id="score-footer"><span>🗂️ PinnaQuest Detective Agency</span><span>SCORE: <span id="score-val">0</span></span></div>
  </div>
  <div>
    <div class="panel">
      <div class="panel-title">📋 Evidence Log</div>
      <div class="clue-list" id="clue-list">
        <div class="clue-empty">No evidence yet.<br>Answer correctly to uncover clues...</div>
      </div>
    </div>
  </div>
</div>

<div class="overlay show" id="overlay-instructions">
  <div class="overlay-card">
    <div class="overlay-title">🔍 Detective Agency</div>
    <div class="overlay-sub">A cold case. Six suspects. Only your wits can crack it.</div>
    <div class="rules-list">
      <div class="rule-row"><div class="rule-icon">🚔</div><div class="rule-text">Six suspects are in the lineup. <b>One of them is guilty</b> — your job is to figure out who.</div></div>
      <div class="rule-row"><div class="rule-icon">✅</div><div class="rule-text">Every correct answer reveals a <b>clue</b> about the guilty suspect.</div></div>
      <div class="rule-row"><div class="rule-icon">❌</div><div class="rule-text">Wrong answers cost you a <b>key</b>. Lose all 3 and the suspect walks free.</div></div>
      <div class="rule-row"><div class="rule-icon">🔎</div><div class="rule-text">Use clues to <b>eliminate suspects</b> automatically from the lineup.</div></div>
      <div class="rule-row"><div class="rule-icon">⚖️</div><div class="rule-text">At the end, make your <b>accusation</b> for a big score bonus and XP!</div></div>
    </div>
    <button class="btn-case" onclick="closeInstructions()">Open Case File →</button>
  </div>
</div>

<div class="overlay" id="overlay-scene">
  <div class="overlay-card">
    <span class="scene-emoji">🌧️🔍🚔</span>
    <div class="scene-line">Rain hammers the city tonight.</div>
    <div class="scene-line">Six suspects sit in the lineup, each with a story.</div>
    <div class="scene-line">But one of them is lying.</div>
    <div class="scene-line highlight">You have the questions. Find the truth.</div>
    <button class="btn-case" onclick="startGame()" style="margin-top:18px;">Begin Interrogation →</button>
  </div>
</div>

<div class="overlay" id="overlay-accuse">
  <div class="overlay-card" style="max-width:700px;">
    <div class="overlay-title">⚖️ Make Your Accusation</div>
    <div class="overlay-sub">You've heard the evidence. Point the finger — who's guilty?</div>
    <div class="accuse-grid" id="accuse-grid"></div>
  </div>
</div>

<div class="overlay" id="overlay-result">
  <div class="overlay-card">
    <span class="result-emoji" id="res-emoji">🏆</span>
    <div class="overlay-title" id="res-title">CASE CLOSED!</div>
    <div class="overlay-sub" id="res-sub"></div>
    <div class="result-stats">
      <div class="rstat"><span class="rv" id="res-correct">0</span><span class="rl">Correct</span></div>
      <div class="rstat"><span class="rv" id="res-score">0</span><span class="rl">Score</span></div>
      <div class="rstat"><span class="rv" id="res-acc">0%</span><span class="rl">Accuracy</span></div>
    </div>
    <div class="xp-badge" id="xp-badge" style="display:none;">+0 XP EARNED!</div>
    <div class="result-btns">
      <button class="btn-ghost" onclick="retakeCurrentGame(this)">↻ Retake Game</button>
      <button class="btn-ghost" onclick="window.location.href='quizzes.php'">🔄 New Case</button>
      <button class="btn-case"  onclick="window.location.href='studentdashboard.php'">🏠 Dashboard</button>
    </div>
  </div>
</div>

<script>

const QUESTIONS = <?php echo json_encode(array_values($mcq)); ?>;
const TOTAL_Q = QUESTIONS.length;
const TIME_PER_Q = 20;
const MAX_LIVES = 3;

// ── Images embedded as base64 data URIs (no external files needed) ──
const IMGS = {
  bg:        "data:image/png;base64,",
  malone:    "data:image/png;base64,",
  scarlett:  "data:image/png;base64,",
  phantom:   "data:image/png;base64,",
  vex:       "data:image/png;base64,",
  jade:      "data:image/png;base64,",
  silhouette:"data:image/png;base64,"
};

// Set background immediately
document.getElementById('bg-img').style.backgroundImage = 'url(' + IMGS.bg + ')';

const SUSPECTS = [
  { id:0, name:'Pedro', color:'crimson',  accessory:'lockpick',  style:'trenchcoat', imgKey:'malone'     },
  { id:1, name:'Maria',    color:'crimson',  accessory:'briefcase', style:'fedora',      imgKey:'scarlett'   },
  { id:2, name:'Juan', color:'sapphire', accessory:'lockpick',  style:'shadow',      imgKey:'phantom'    },
  { id:3, name:'Juanna',       color:'sapphire', accessory:'disguise',  style:'trenchcoat',  imgKey:'vex'        },
  { id:4, name:'Jose',      color:'emerald',  accessory:'briefcase', style:'fedora',      imgKey:'jade'       },
  { id:5, name:'Antonio',   color:'emerald',  accessory:'disguise',  style:'shadow',      imgKey:'silhouette' },
];

const COLOR_LABEL = { crimson:'Scarlet', sapphire:'Cobalt', emerald:'Jade' };
const ACC_EMOJI   = { lockpick:'🔑', briefcase:'💼', disguise:'🎭' };
const ACC_LABEL   = { lockpick:'Lockpick', briefcase:'Briefcase', disguise:'Disguise Kit' };
const STYLE_EMOJI = { trenchcoat:'🧥', fedora:'🎩', shadow:'👤' };
const STYLE_LABEL = { trenchcoat:'Trenchcoat', fedora:'Fedora', shadow:'Shadow' };

function shuffle(arr){const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}

let impostor=SUSPECTS[Math.floor(Math.random()*SUSPECTS.length)];
let cluePool=buildCluePool(impostor),clueIdx=0,revealedClues=[];
let currentIdx=0,score=0,correctCount=0,lives=MAX_LIVES;
let answered=false,timerSecs=TIME_PER_Q,timerIv=null;

function buildCluePool(imp){
  const pool=[];
  ['color','accessory','style'].forEach(cat=>{
    const impVal=imp[cat];
    pool.push({cat,val:impVal,positive:true});
    [...new Set(SUSPECTS.map(s=>s[cat]))].filter(v=>v!==impVal).forEach(otherVal=>{
      pool.push({cat,val:otherVal,positive:false});
    });
  });
  return shuffle(pool);
}
cluePool=buildCluePool(impostor);

function clueText(c){
  if(c.cat==='color')     return c.positive?`Suspect's tie is <b>${COLOR_LABEL[c.val]}</b>.`:`Suspect does <b>NOT</b> wear a ${COLOR_LABEL[c.val]} tie.`;
  if(c.cat==='accessory') return c.positive?`Suspect was carrying a <b>${ACC_LABEL[c.val]}</b> ${ACC_EMOJI[c.val]}.`:`No ${ACC_LABEL[c.val]} ${ACC_EMOJI[c.val]} on the suspect.`;
  return c.positive?`Suspect wears a <b>${STYLE_LABEL[c.val]}</b> ${STYLE_EMOJI[c.val]}.`:`Suspect is <b>NOT</b> the ${STYLE_LABEL[c.val]} type.`;
}

function computePossible(){
  let set=SUSPECTS.map(s=>s.id);
  revealedClues.forEach(c=>{set=set.filter(id=>{const s=SUSPECTS[id];return c.positive?(s[c.cat]===c.val):(s[c.cat]!==c.val);});});
  return set;
}

// Build character card HTML using embedded base64 image
function charHTML(s, extraClass, interactive){
  const num=s.id+1;
  const shadowClass=s.style==='shadow'?'type-shadow':'';
  const wrapClass=interactive?`accuse-card ${shadowClass}`:`char-figure ${shadowClass} ${extraClass}`;
  const clickAttr=interactive?`onclick="makeAccusation(${s.id})"`:'';
  const badge=!interactive?`<div class="lineup-num">${num}</div>`:'';
  const imgSrc=IMGS[s.imgKey];
  return `
  <div class="${wrapClass}" ${clickAttr}>
    ${badge}
    <div class="char-img-wrap">
      <img class="char-img" src="${imgSrc}" alt="${s.name}">
    </div>
    <div class="char-nameplate">${s.name}</div>
    <div class="char-traits">
      <span>${COLOR_LABEL[s.color]}</span>
      <span>${ACC_EMOJI[s.accessory]}</span>
      <span>${STYLE_EMOJI[s.style]}</span>
    </div>
  </div>`;
}

function renderSuspects(){
  const possible=computePossible();
  document.getElementById('suspect-grid').innerHTML=SUSPECTS.map(s=>{
    const isPossible=possible.includes(s.id);
    const isElim=revealedClues.length>0&&!isPossible;
    const cls=isElim?'eliminated':(isPossible&&revealedClues.length>0?'possible':'');
    const sc=s.style==='shadow'?'type-shadow':'';
    return charHTML(s,`${cls} ${sc}`.trim(),false);
  }).join('');
}

function renderClueLog(){
  const list=document.getElementById('clue-list');
  if(revealedClues.length===0){list.innerHTML='<div class="clue-empty">No evidence yet.<br>Answer correctly to uncover clues about the guilty suspect...</div>';return;}
  list.innerHTML=revealedClues.map((c,i)=>`<div class="clue-item"><span class="clue-num">#${String(i+1).padStart(2,'0')}</span>${clueText(c)}</div>`).join('');
  list.scrollTop=list.scrollHeight;
}
function updateInvestBar(){document.getElementById('invest-fill').style.width=Math.min(100,Math.round(revealedClues.length/cluePool.length*100))+'%';}

function closeInstructions(){sfxClick();document.getElementById('overlay-instructions').classList.remove('show');document.getElementById('overlay-scene').classList.add('show');}
function startGame(){startBgAmbient();document.getElementById('overlay-scene').classList.remove('show');
// Global click sound for answer buttons + result buttons
document.addEventListener('click', function(e){
  const btn = e.target.closest('.ans-btn, .btn-case, .btn-ghost, .btn-case[onclick]');
  if(btn && !btn.disabled) sfxClick();
}, true);

renderSuspects();renderClueLog();showQuestion(0);}

function updateHUD(){
  document.getElementById('hud-q').innerText=`${currentIdx+1}/${TOTAL_Q}`;
  document.getElementById('hud-score').innerText=score;
  document.getElementById('score-val').innerText=score;
  document.querySelectorAll('.life-badge').forEach((el,i)=>{el.classList.toggle('lost',i>=lives);});
}
function getCorrectIndex(q){
  if(typeof q.answer_index==='number'&&q.answer_index>=0&&q.answer_index<4)return q.answer_index;
  if(Array.isArray(q.options)){const idx=q.options.findIndex(o=>(o||'').trim()===(q.answer||'').trim());if(idx!==-1)return idx;}
  return 0;
}
function showQuestion(idx){
  if(idx>=TOTAL_Q){startAccusation();return;}
  const q=QUESTIONS[idx];answered=false;
  document.getElementById('q-text').innerText=q.question||'(no question)';
  const opts=q.options||[];
  for(let i=0;i<4;i++){const btn=document.getElementById(`ans-${i}`);const txt=document.getElementById(`ans-text-${i}`);btn.disabled=false;btn.classList.remove('correct-flash','wrong-fade');btn.style.opacity='1';txt.innerText=opts[i]||'';}
  updateHUD();startTimer();
}
function startTimer(){clearInterval(timerIv);timerSecs=TIME_PER_Q;renderTimer();timerIv=setInterval(()=>{if(answered)return;timerSecs--;renderTimer();if(timerSecs<=0){clearInterval(timerIv);answerQuestion(-99);}},1000);}
function renderTimer(){const fill=document.getElementById('timer-fill');fill.style.width=((timerSecs/TIME_PER_Q)*100)+'%';fill.classList.toggle('danger',timerSecs<=6);}
function showBanner(text,type){const b=document.getElementById('feedback-banner');b.innerText=text;b.className=`show ${type}`;setTimeout(()=>{b.className='';},1600);}
function showScorePop(pts,btn){const el=document.createElement('div');el.className='score-pop-fx';el.innerText=`+${pts}`;const r=btn.getBoundingClientRect();el.style.left=`${r.left+r.width/2-24}px`;el.style.top=`${r.top+r.height/2}px`;document.body.appendChild(el);setTimeout(()=>el.remove(),1200);}

function answerQuestion(sel){
  if(answered)return;answered=true;clearInterval(timerIv);
  const q=QUESTIONS[currentIdx];const ci=getCorrectIndex(q);const ok=(sel===ci);
  for(let i=0;i<4;i++){const btn=document.getElementById(`ans-${i}`);btn.disabled=true;if(i===ci)btn.classList.add('correct-flash');else if(i===sel&&!ok)btn.classList.add('wrong-fade');else btn.style.opacity='.28';}
  if(ok){sfxCorrect();if(revealedClues.length>0)sfxClue();correctCount++;const pts=400+timerSecs*15;score+=pts;showBanner('📋 Clue revealed! Evidence logged.','ok');showScorePop(pts,document.getElementById(`ans-${sel}`));if(clueIdx<cluePool.length){revealedClues.push(cluePool[clueIdx]);clueIdx++;}renderClueLog();renderSuspects();updateInvestBar();}
  else{sfxWrong();lives--;showBanner(lives>0?'🚔 Wrong lead — suspect stays quiet...':'🚨 No more keys!','bad');}
  updateHUD();
  setTimeout(()=>{if(lives<=0){endGameEarly();return;}currentIdx++;showQuestion(currentIdx);},1500);
}
function startAccusation(){document.getElementById('accuse-grid').innerHTML=SUSPECTS.map(s=>charHTML(s,'',true)).join('');document.getElementById('overlay-accuse').classList.add('show');}
function makeAccusation(gid){sfxAccuse();document.getElementById('overlay-accuse').classList.remove('show');const ok=(gid===impostor.id);if(ok)score+=2000;finishGame(ok,true);}
function endGameEarly(){finishGame(false,false);}
function finishGame(ok,madeAccuse){
  const acc=TOTAL_Q>0?Math.round(correctCount/TOTAL_Q*100):0;
  let emoji,title,sub;
  if(!madeAccuse){sfxFail();emoji='🌧️';title='SUSPECT WALKS FREE';sub=`You lost all your keys. The guilty party was ${impostor.name}.`;}
  else if(ok){sfxVictory();emoji='🏆';title='CASE CLOSED!';sub=`You nailed it — ${impostor.name} was the guilty one!`;spawnConfetti();}
  else{sfxFail();emoji='🎭';title='WRONG ACCUSATION';sub=`Wrong person. The guilty party was ${impostor.name}.`;}
  document.getElementById('res-emoji').innerText=emoji;
  document.getElementById('res-title').innerText=title;
  document.getElementById('res-sub').innerText=sub;
  document.getElementById('res-correct').innerText=correctCount;
  document.getElementById('res-score').innerText=score;
  document.getElementById('res-acc').innerText=acc+'%';
  const completionToken = (window.crypto && crypto.randomUUID) ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
  window.gameResultSavePromise = fetch('save_quiz_result.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:`score=${score}&correct_answers=${correctCount}&total_questions=${TOTAL_Q}&completion_token=${encodeURIComponent(completionToken)}`}).then(r=>r.json()).then(d=>{if(d.success){const b=document.getElementById('xp-badge');b.innerText=d.xp_earned>0?`+${d.xp_earned} XP EARNED!`:(d.xp_message||'No quiz XP awarded.');b.style.display='inline-block';}}).catch(()=>{});
  document.getElementById('overlay-result').classList.add('show');
}
function spawnConfetti(){const colors=['#fbbf24','#ec4899','#10b981','#3b82f6','#7c3aed','#f97316','#e2e8f0'];for(let i=0;i<80;i++){const el=document.createElement('div');el.className='conf-bit';const sz=5+Math.floor(Math.random()*8);el.style.cssText=`left:${Math.random()*100}vw;top:-20px;width:${sz}px;height:${sz*(Math.random()>.5?1:2)}px;background:${colors[Math.floor(Math.random()*colors.length)]};--cd:${1.4+Math.random()*1.8}s;--cl:${Math.random()*.8}s;border-radius:${Math.random()>.5?'50%':'2px'};`;document.body.appendChild(el);setTimeout(()=>el.remove(),3500);}}
(function initRain(){const layer=document.getElementById('rain-layer');for(let i=0;i<65;i++){const drop=document.createElement('div');drop.className='rain-drop';const h=10+Math.random()*20;drop.style.cssText=`left:${Math.random()*110}vw;height:${h}px;opacity:${0.12+Math.random()*.2};--rd:${0.42+Math.random()*.65}s;--rl:${-(Math.random()*2)}s;`;layer.appendChild(drop);}})();

// Global click sound for answer buttons + result buttons
document.addEventListener('click', function(e){
  const btn = e.target.closest('.ans-btn, .btn-case, .btn-ghost, .btn-case[onclick]');
  if(btn && !btn.disabled) sfxClick();
}, true);

renderSuspects();renderClueLog();

// ══════════════════════════════════════════════════════════════
//  DETECTIVE AUDIO ENGINE — Web Audio API (no external files)
//  Noir jazz ambience + click / correct / wrong / reveal SFX
// ══════════════════════════════════════════════════════════════
const _AudioCtx = window.AudioContext || window.webkitAudioContext;
let _actx = null;
let _bgStarted = false;
let _bgNodes = [];
let _masterGain = null;

function getCtx(){
  if(!_actx){ _actx = new _AudioCtx(); _masterGain = _actx.createGain(); _masterGain.gain.value = 0.85; _masterGain.connect(_actx.destination); }
  if(_actx.state === 'suspended') _actx.resume();
  return _actx;
}
function dest(){ return _masterGain; }

function playTone(freq, type, start, dur, vol, ramp){
  const ctx = getCtx();
  const osc = ctx.createOscillator();
  const g   = ctx.createGain();
  osc.type = type;
  osc.frequency.setValueAtTime(freq, start);
  g.gain.setValueAtTime(vol, start);
  g.gain.exponentialRampToValueAtTime(0.0001, start + (ramp||dur));
  osc.connect(g); g.connect(dest());
  osc.start(start); osc.stop(start + dur + 0.02);
}

// ── SFX: typewriter click ─────────────────────────────────────
function sfxClick(){
  const ctx = getCtx(); const t = ctx.currentTime;
  const buf = ctx.createBuffer(1, Math.floor(ctx.sampleRate*0.045), ctx.sampleRate);
  const d = buf.getChannelData(0);
  for(let i=0;i<d.length;i++) d[i] = (Math.random()*2-1)*(1 - i/d.length)*(i<20 ? i/20 : 1);
  const src = ctx.createBufferSource(); src.buffer = buf;
  const flt = ctx.createBiquadFilter(); flt.type='bandpass'; flt.frequency.value=1400; flt.Q.value=1.2;
  const g = ctx.createGain(); g.gain.setValueAtTime(0.4, t); g.gain.exponentialRampToValueAtTime(0.0001, t+0.055);
  src.connect(flt); flt.connect(g); g.connect(dest());
  src.start(t);
}

// ── SFX: correct answer (rising detective arpeggio) ───────────
function sfxCorrect(){
  const ctx = getCtx(); const t = ctx.currentTime;
  [[294,.00],[370,.10],[440,.20],[587,.33]].forEach(([f,d])=> playTone(f,'triangle',t+d,0.28,0.16));
  playTone(98,'sine',t,0.45,0.28);
}

// ── SFX: wrong answer (descending dissonance) ─────────────────
function sfxWrong(){
  const ctx = getCtx(); const t = ctx.currentTime;
  playTone(233,'sawtooth',t,    0.22,0.20);
  playTone(207,'sawtooth',t+.18,0.28,0.22);
  playTone(164,'sawtooth',t+.36,0.34,0.24);
}

// ── SFX: clue reveal (mysterious ping) ───────────────────────
function sfxClue(){
  const ctx = getCtx(); const t = ctx.currentTime;
  playTone(523,'sine',t,     0.7,0.12);
  playTone(415,'sine',t+.12, 0.6,0.09);
  playTone(330,'sine',t+.24, 0.8,0.07);
}

// ── SFX: accusation / big action click ───────────────────────
function sfxAccuse(){
  const ctx = getCtx(); const t = ctx.currentTime;
  playTone(440,'square',t,    0.09,0.22);
  playTone(330,'square',t+.08,0.12,0.18);
  playTone(220,'sine',  t+.15,0.35,0.20);
}

// ── SFX: victory (case closed jazz fanfare) ───────────────────
function sfxVictory(){
  const ctx = getCtx(); const t = ctx.currentTime;
  [[392,.00],[440,.18],[494,.36],[587,.55],[494,.78],[587,.96],[784,1.2]].forEach(([f,d])=>
    playTone(f,'triangle',t+d,0.25,0.20));
  [[196,.00],[220,.18],[247,.36],[294,.55]].forEach(([f,d])=>
    playTone(f,'sine',t+d,0.35,0.26));
}

// ── SFX: fail (suspect walks free) ───────────────────────────
function sfxFail(){
  const ctx = getCtx(); const t = ctx.currentTime;
  playTone(196,'sawtooth',t,    0.5, 0.26);
  playTone(174,'sawtooth',t+.4, 0.6, 0.28);
  playTone(147,'sawtooth',t+.88,0.75,0.30);
}

// ══════════════════════════════════════════════════════════════
//  BACKGROUND AMBIENT: Noir Jazz + Rain
// ══════════════════════════════════════════════════════════════
function startBgAmbient(){
  if(_bgStarted) return; _bgStarted = true;

  // ── Play uploaded background audio file ──
  const music = document.getElementById('bg-music');
  if(music){
    music.volume = 0.38;
    music.play().catch(()=>{
      // Autoplay blocked — starts on first user interaction
      document.addEventListener('click', ()=>{ music.play(); }, { once: true });
    });
  }
}

</script>
